        if (self.owner) |owner| owner.destroy.?(owner.ref);
    }

    /// The vtable whose slots call the methods of T, which embeds it as the named field.
    pub fn implement(comptime T: type, comptime field: []const u8) c.ke_gpu_render_target {
        return .{
            .acquire = &struct {
                fn call(self: ?*c.ke_gpu_render_target, a0: ?*c.ke_gpu_texture_view) callconv(.c) abi_result.c.ke_result {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return resultOf(error.Failed)));
                    const value = T.acquire(state) catch |failure| return resultOf(failure);
                    (a0 orelse return resultOf(error.Failed)).* = value;
                    return abi_result.c.KE_OK;
                }
            }.call,
            .present = &struct {
                fn call(self: ?*c.ke_gpu_render_target) callconv(.c) abi_result.c.ke_result {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return resultOf(error.Failed)));
                    T.present(state) catch |failure| return resultOf(failure);
                    return abi_result.c.KE_OK;
                }
            }.call,
            .size = &struct {
                fn call(self: ?*c.ke_gpu_render_target, a0: ?*u32, a1: ?*u32) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.size(state, a0, a1);
                }
            }.call,
            .format = &struct {
                fn call(self: ?*c.ke_gpu_render_target) callconv(.c) c.ke_gpu_texture_format {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return std.mem.zeroes(c.ke_gpu_texture_format)));
                    return @intFromEnum(T.format(state));
                }
            }.call,
        };
    }

    /// Begins a frame and writes the view to draw into, owned by the target and valid until present.
    /// Succeeds writing KE_GPU_INVALID_HANDLE when the target has nothing to draw into this frame,
    /// and fails writing it when acquiring failed.
    pub fn acquire(self: GpuRenderTarget) Error!c.ke_gpu_texture_view {
        var written: c.ke_gpu_texture_view = undefined;
        try checkResult(self.ptr.acquire.?(self.ptr, &written));
        return written;
    }

    /// Ends the frame begun by acquire. Fails with KE_RESULT_INVALID_ARGUMENT when no frame is
    /// acquired.
    pub fn present(self: GpuRenderTarget) Error!void {
        try checkResult(self.ptr.present.?(self.ptr));
    }

    /// Size in pixels of the view the last acquire returned, or of the next one before any acquire.
    pub fn size(self: GpuRenderTarget, out_width: ?*u32, out_height: ?*u32) void {
        return self.ptr.size.?(self.ptr, out_width, out_height);
    }

    /// Texel format of every view acquire returns.
    pub fn format(self: GpuRenderTarget) GpuTextureFormat {
        return @enumFromInt(self.ptr.format.?(self.ptr));
    }

};

pub const RenderResourceBinder = struct {
    ptr: *c.ke_render_resource_binder,
    owner: ?c.ke_render_resource_binder_handle = null,

    pub fn deinit(self: RenderResourceBinder) void {
        if (self.owner) |owner| owner.destroy.?(owner.ref);
    }

    /// The vtable whose slots call the methods of T, which embeds it as the named field.
    pub fn implement(comptime T: type, comptime field: []const u8) c.ke_render_resource_binder {
        return .{
            .provide = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: ?*const c.ke_render_shader_binding) callconv(.c) abi_result.c.ke_result {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return resultOf(error.Failed)));
                    T.provide(state, a0) catch |failure| return resultOf(failure);
                    return abi_result.c.KE_OK;
                }
            }.call,
            .create_shader_layout = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: ?*const c.ke_render_shader_layout_params, a1: ?*c.ke_render_shader_layout) callconv(.c) abi_result.c.ke_result {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return resultOf(error.Failed)));
                    const value = T.createShaderLayout(state, a0) catch |failure| return resultOf(failure);
                    (a1 orelse return resultOf(error.Failed)).* = value;
                    return abi_result.c.KE_OK;
                }
            }.call,
            .destroy_shader_layout = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: c.ke_render_shader_layout) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.destroyShaderLayout(state, a0);
                }
            }.call,
            .pipeline_layouts = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: c.ke_render_shader_layout, a1: ?[*]c.ke_gpu_bind_group_layout, a2: u32, a3: ?*u32) callconv(.c) abi_result.c.ke_result {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return resultOf(error.Failed)));
                    T.pipelineLayouts(state, a0, a1, a2, a3) catch |failure| return resultOf(failure);
                    return abi_result.c.KE_OK;
                }
            }.call,
            .create_set = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: c.ke_render_shader_layout, a1: ?[*:0]const u8, a2: ?[*:0]const u8, a3: ?[*]const c.ke_render_shader_binding, a4: u32, a5: ?*c.ke_render_resource_set) callconv(.c) abi_result.c.ke_result {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return resultOf(error.Failed)));
                    const value = T.createSet(state, a0, std.mem.span(a1 orelse return resultOf(error.Failed)), std.mem.span(a2 orelse return resultOf(error.Failed)), if (a3) |items| items[0..a4] else &.{}) catch |failure| return resultOf(failure);
                    (a5 orelse return resultOf(error.Failed)).* = value;
                    return abi_result.c.KE_OK;
                }
            }.call,
            .destroy_set = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: c.ke_render_resource_set) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.destroySet(state, a0);
                }
            }.call,
            .bind_render_set = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: ?*c.ke_gpu_render_pass, a1: c.ke_render_resource_set, a2: ?[*]const u32, a3: u32) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.bindRenderSet(state, GpuRenderPass{ .ptr = a0 orelse return }, a1, if (a2) |items| items[0..a3] else &.{});
                }
            }.call,
            .bind_compute_set = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: ?*c.ke_gpu_compute_pass, a1: c.ke_render_resource_set, a2: ?*const u32, a3: u32) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.bindComputeSet(state, GpuComputePass{ .ptr = a0 orelse return }, a1, a2, a3);
                }
            }.call,
            .create_material = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: ?*const c.ke_render_material_data, a1: ?*c.ke_render_material_binding) callconv(.c) abi_result.c.ke_result {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return resultOf(error.Failed)));
                    const value = T.createMaterial(state, a0) catch |failure| return resultOf(failure);
                    (a1 orelse return resultOf(error.Failed)).* = value;
                    return abi_result.c.KE_OK;
                }
            }.call,
            .destroy_material = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: c.ke_render_material_binding) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.destroyMaterial(state, a0);
                }
            }.call,
            .bind_material = &struct {
                fn call(self: ?*c.ke_render_resource_binder, a0: ?*c.ke_gpu_render_pass, a1: c.ke_render_shader_layout, a2: c.ke_render_material_binding) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.bindMaterial(state, GpuRenderPass{ .ptr = a0 orelse return }, a1, a2);
                }
            }.call,
        };
    }

    /// Makes `binding` the resource of every shader parameter of its name that a resource set leaves
    /// out. The name is copied.
    pub fn provide(self: RenderResourceBinder, binding: ?*const c.ke_render_shader_binding) Error!void {
        try checkResult(self.ptr.provide.?(self.ptr, binding));
    }

    /// Builds the layout of a compiled shader from what the build recorded about it.
    pub fn createShaderLayout(self: RenderResourceBinder, params: ?*const c.ke_render_shader_layout_params) Error!c.ke_render_shader_layout {
        var written: c.ke_render_shader_layout = undefined;
        try checkResult(self.ptr.create_shader_layout.?(self.ptr, params, &written));
        return written;
    }

    /// Destroys a layout; the invalid one is ignored. A set created against it must be destroyed
    /// first.
    pub fn destroyShaderLayout(self: RenderResourceBinder, layout: c.ke_render_shader_layout) void {
        return self.ptr.destroy_shader_layout.?(self.ptr, layout);
    }

    /// Fills the bind group layouts a pipeline running the shader of `layout` declares.
    pub fn pipelineLayouts(self: RenderResourceBinder, layout: c.ke_render_shader_layout, out_layouts: ?[*]c.ke_gpu_bind_group_layout, capacity: u32, out_count: ?*u32) Error!void {
        try checkResult(self.ptr.pipeline_layouts.?(self.ptr, layout, out_layouts, capacity, out_count));
    }

    /// Binds resources to one group of a shader by the names its parameters carry. A parameter left
    /// out is bound to what `provide` gave under its name.
    pub fn createSet(self: RenderResourceBinder, layout: c.ke_render_shader_layout, block: [:0]const u8, label: [:0]const u8, bindings: []const c.ke_render_shader_binding) Error!c.ke_render_resource_set {
        var written: c.ke_render_resource_set = undefined;
        try checkResult(self.ptr.create_set.?(self.ptr, layout, block.ptr, label.ptr, bindings.ptr, @intCast(bindings.len), &written));
        return written;
    }

    /// Destroys a set; the invalid one is ignored.
    pub fn destroySet(self: RenderResourceBinder, set: c.ke_render_resource_set) void {
        return self.ptr.destroy_set.?(self.ptr, set);
    }

    /// Makes the resources of `set` those the next draws of `pass` read, with one dynamic offset per
    /// binding hinted KE_RENDER_BINDING_HINT_DYNAMIC_OFFSET, in the order the shader declares them.
    pub fn bindRenderSet(self: RenderResourceBinder, pass: GpuRenderPass, set: c.ke_render_resource_set, dynamic_offsets: []const u32) void {
        return self.ptr.bind_render_set.?(self.ptr, pass.ptr, set, dynamic_offsets.ptr, @intCast(dynamic_offsets.len));
    }

    /// Makes the resources of `set` those the next dispatches of `pass` read, as bind_render_set
    /// does.
    pub fn bindComputeSet(self: RenderResourceBinder, pass: GpuComputePass, set: c.ke_render_resource_set, dynamic_offsets: ?*const u32, dynamic_offset_count: u32) void {
        return self.ptr.bind_compute_set.?(self.ptr, pass.ptr, set, dynamic_offsets, dynamic_offset_count);
    }

    /// Keeps the data of one material for the shaders that draw with it. The texture views are
    /// borrowed and must outlive the binding.
    pub fn createMaterial(self: RenderResourceBinder, data: ?*const c.ke_render_material_data) Error!c.ke_render_material_binding {
        var written: c.ke_render_material_binding = undefined;
        try checkResult(self.ptr.create_material.?(self.ptr, data, &written));
        return written;
    }

    /// Destroys a material binding; the invalid one is ignored.
    pub fn destroyMaterial(self: RenderResourceBinder, material: c.ke_render_material_binding) void {
        return self.ptr.destroy_material.?(self.ptr, material);
    }

    /// Makes `material` the one the next draws of `pass` with the shader of `layout` read. An
    /// unknown material or a shader that declares no material binds nothing.
    pub fn bindMaterial(self: RenderResourceBinder, pass: GpuRenderPass, layout: c.ke_render_shader_layout, material: c.ke_render_material_binding) void {
        return self.ptr.bind_material.?(self.ptr, pass.ptr, layout, material);
    }

};

